   </main>
  </div>
  <DialogHost/><div v-if="state.notice" class="toast" role="status"><i class="las la-check-circle"></i>{{state.notice}}</div>
 </div>
</template>
<script setup>
import {ref,computed,inject,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import Grid from './Grid.vue';
import {MessageCellEditor} from './MessageCellEditor.mjs';
