const screen=ref(screenDefs[location.hash.slice(1)]?location.hash.slice(1):'admcode');const def=computed(()=>screenDefs[screen.value]);const filters=ref({}),applied=ref({}),rows=ref([]),baseline=ref([]),selected=ref([]),trail=ref([]),page=ref(1),pageSize=ref(20),pages=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),tick=ref(0),grid=ref(null),mobileNav=ref(false),filtersOpen=ref(true);let generation=0,disposed=false;
