const visibleRows=computed(()=>{if(screen.value!=='admmenu'||!applied.value.name)return rows.value;const q=applied.value.name.toLowerCase();const matches=rows.value.filter(r=>`${r.program} ${JSON.stringify(r.locale)}`.toLowerCase().includes(q));return rows.value.filter(r=>matches.some(m=>m.id===r.id||m.path?.startsWith(r.path+'/')));});
const sidebar=ref(null);const langs=computed(()=>s.languages);watch(mobileNav,async open=>{await nextTick();if(open)sidebar.value?.querySelector('button')?.focus();else document.querySelector('.topbar .mobile-toggle')?.focus();});
function errorText(e){return e.status!==undefined?s.errorText(e):e.message;}
async function load(){const id=++generation;loading.value=true;error.value='';selected.value=[];try{const result=await api.list(def.value.resource,{...applied.value,page:page.value,pageSize:pageSize.value,...(screen.value==='admcode'?{parentId:trail.value.at(-1)?.id||''}:{})});if(id!==generation||disposed)return;rows.value=(screen.value==='admmenu'?flatten(result):result.contents).map(r=>({...r,_key:r.id||r.code}));baseline.value=clone(rows.value);total.value=screen.value==='admmenu'?rows.value.length:result.totalItems;pages.value=screen.value==='admmenu'?1:result.totalPages;if(page.value>Math.max(1,pages.value)){page.value=Math.max(1,pages.value);return await load();}}catch(e){if(id===generation){error.value=errorText(e);throw e;}}finally{if(id===generation)loading.value=false;}}
async function runLoad(){try{await load();}catch{}}
async function guard(){grid.value?.stop();tick.value++;if(saving.value)return false;if(!dirty.value)return true;const result=await s.dialog.open({kind:'confirm',title:t('unsaved'),message:t('unsaved_hint'),submitLabel:t('save_leave'),onSubmit:async()=>{await save(true);},alternative:{label:t('discard_leave'),action:()=>{rows.value=clone(baseline.value);}}});return result.status==='submitted';}
async function navigate(key){if(key===screen.value){mobileNav.value=false;return;}if(!await guard())return;screen.value=key;filters.value={};applied.value={};trail.value=[];page.value=1;mobileNav.value=false;history.replaceState(null,'','#'+key);await runLoad();}
async function changeLocale(locale){if(!await guard())return;if(config.mode!=='preview'){const next=new URL(location.href);next.searchParams.set('lang',locale);location.assign(next.href);return;}state.locale=locale;document.documentElement.lang=locale.replace('_','-');}
async function search(){if(!await guard())return;applied.value=clone(filters.value);page.value=1;await runLoad();}
function resetFilters(){filters.value={};}
async function refresh(){if(await guard())await runLoad();}
async function movePage(value){if(await guard()){page.value=value;await runLoad();}}
async function setPageSize(value){if(await guard()){pageSize.value=value;page.value=1;await runLoad();}}
async function goLevel(index){if(!await guard())return;trail.value=trail.value.slice(0,index+1);page.value=1;filters.value={};applied.value={};await runLoad();}
async function descend(row){if(!row.id)return;if(!await guard())return;trail.value.push(clone(row));page.value=1;applied.value={};filters.value={};await runLoad();}
function badge(text,kind=''){const span=document.createElement('span');span.className='status-badge '+kind;span.textContent=text;return span;}
function actionButton(label,icon,fn,danger=false){const b=document.createElement('button');b.className='row-action'+(danger?' danger':'');b.type='button';b.setAttribute('aria-label',label);b.title=label;const i=document.createElement('i');i.className=icon;const text=document.createElement('span');text.textContent=label;b.append(i,text);b.onclick=e=>{e.stopPropagation();fn();};return b;}
const columns=computed(()=>{tick.value;const list=[];if(def.value.batch)list.push({headerName:t('status'),width:84,minWidth:84,cellRenderer:p=>{const value=rowState(p.data,baseline.value);return value?badge(t(value),value):badge('—','neutral');}});const simple=(field,title,width=150,editable=false)=>({field,headerName:t(title),width,editable:p=>editable&&!p.data._deleted});const local=(field,title,width=240)=>({headerName:t(title),width,valueGetter:p=>localeValue(p.data,state.locale,field),cellRenderer:p=>{const el=document.createElement('span');el.className=field==='name'||field==='label'?'name-cell':'muted';el.textContent=p.value||'—';if(screen.value==='admmenu')el.style.paddingLeft=Math.min(p.data._depth,4)*18+'px';return el;}});
if(screen.value==='admcode')list.push({...simple('code','code',165,true),editable:p=>!p.data.id&&!p.data._deleted,cellClass:'mono-cell'},local('name','code_name',205),local('remarks','remarks',310));
if(screen.value==='admmsge'){list.push({...simple('code','code',260),editable:p=>!p.data._deleted&&!baseline.value.some(r=>r._key===p.data._key),cellClass:'mono-cell'});for(const lang of langs.value)list.push({colId:'locale_'+lang.code,headerName:lang.label+' · '+lang.code,width:270,cellClass:'message-cell',valueGetter:p=>p.data.locale?.[lang.code]||'',valueSetter:p=>{p.data.locale??={};p.data.locale[lang.code]=p.newValue;return true;},editable:p=>!p.data._deleted,cellEditor:MessageCellEditor,cellEditorPopup:false});}
if(screen.value==='admmenu')list.push(local('label','label',270),simple('program','program',155),simple('path','path',240));
if(screen.value==='admauth')list.push({...simple('role','role',210),cellClass:'mono-cell'},simple('name','name',210),simple('type','type',110),simple('remarks','remarks',280));
if(screen.value==='aduser')list.push({...simple('username','username',175),cellClass:'mono-cell'},simple('name','name',145),simple('email','email',230),{...simple('status','status',125),cellRenderer:p=>badge(p.value,p.value==='ACTIVE'?'active':'neutral')},simple('lastLoginAt','last_login',185));
if(['admcode','admmenu','admauth'].includes(screen.value))list.push({...simple('use','use',105),cellRenderer:p=>badge(t(p.value==='Y'?'enabled':'disabled'),p.value==='Y'?'active':'neutral')});if(['admcode','admmenu'].includes(screen.value))list.push(simple('sort','sort',95,screen.value==='admcode'));
list.push({headerName:t('actions'),minWidth:screen.value==='aduser'?330:screen.value==='admauth'?300:190,width:screen.value==='aduser'?350:screen.value==='admauth'?320:screen.value==='admmenu'?260:220,cellRenderer:p=>{const el=document.createElement('div');el.className='row-actions';if(p.data._deleted){el.append(actionButton(t('restore'),'las la-undo',()=>restore(p.data)));return el;}if(screen.value!=='admmsge')el.append(actionButton(t('edit'),'las la-pen',()=>editRow(p.data)));if(screen.value==='admcode'&&p.data.id)el.append(actionButton(t('children'),'las la-folder-open',()=>descend(p.data)));if(screen.value==='admmenu')el.append(actionButton(t('add_child'),'las la-plus',()=>editRow(null,p.data)));if(screen.value==='admauth'){el.append(actionButton(t('menu'),'las la-sitemap',()=>mapAuthority(p.data,'menus')),actionButton(t('users'),'las la-users',()=>mapAuthority(p.data,'users')));}if(screen.value==='aduser'){el.append(actionButton(t('authorities'),'las la-shield-alt',()=>mapUser(p.data)),actionButton(t('reset_password'),'las la-key',()=>resetPassword(p.data)));}if(screen.value!=='admcode')el.append(actionButton(t('delete'),'las la-trash-alt',()=>removeRows([p.data]),true));return el;}});return list;});
function cellEdited(){tick.value++;rows.value=[...rows.value];}
function newRow(parent){const resource=def.value.resource;const locale=Object.fromEntries(langs.value.map(l=>[l.code,resource==='i18n'?'':{[resource==='menu'?'label':'name']:'',remarks:''}]));if(resource==='code')return {id:'',parentId:trail.value.at(-1)?.id||'',code:'',locale,use:'Y',path:trail.value.at(-1)?.path||'',level:trail.value.length,sort:0,extra1:'',extra2:'',extra3:'',extra4:'',extra5:''};if(resource==='i18n')return {code:'',locale};if(resource==='menu')return {id:'',program:'',icon:'las la-folder',locale,use:'Y',sort:0,path:parent?.path||'',level:parent?parent.level+1:0,_depth:parent?parent._depth+1:0,_parentId:parent?.id||''};if(resource==='authority')return {id:'',role:'',type:'ROLE',name:'',remarks:'',use:'Y',users:[],menus:[]};return {id:'',username:'',name:'',email:'',remarks:'',image:'',status:statuses[0]||''};}
async function editRow(row=null,parent=null){if(screen.value==='admmsge'){grid.value?.stop();const added={...newRow(),_key:crypto.randomUUID()};rows.value=[added,...rows.value];tick.value++;await nextTick();grid.value?.edit(0,'code');return;}if(parent&&!parent.id){s.notify('menu_parent_pending');return;}const resource=def.value.resource;let initial=row?clone(row):newRow(parent);try{if(row&&!def.value.batch){initial=await api.detail(resource,row.id);if(resource==='authority')initial=await authorityData(row.id,initial);}}catch(e){error.value=errorText(e);return;}const fixed=resource==='menu'&&row&&isProtected(row,rows.value);const fields=[];const add=(path,label,type='text',extra={})=>fields.push({path,label:t(label),type,...extra});
if(resource==='code'){add('code','code','text',{required:true,readonly:!!row?.id});add('use','use','select',{options:[{value:'Y',label:t('enabled')},{value:'N',label:t('disabled')}]});add('sort','sort','number');}
