const translation=resource==='i18n'?'message':resource==='code'?'name':resource==='menu'?'label':null;const rowLangs=[...langs.value];for(const code of Object.keys(initial.locale||{}))if(!rowLangs.some(l=>l.code===code))rowLangs.push({code,label:code});await s.dialog.open({kind:'form',title:t(row?'edit':'add')+' · '+t(screen.value),subtitle:row?.code||row?.username||row?.role||row?.program,batch:def.value.batch,wide:!!translation,initial,fields,extraTabs:resource==='code',translation,languages:rowLangs,validate:value=>{const err=validate(resource,value,langs.value);return err?t(err):'';},onSubmit:async value=>{if(def.value.batch){if(resource==='code'&&!row){value.path=(trail.value.at(-1)?.path||'')+'/'+value.code;}value._key=row?._key||crypto.randomUUID();if(row){const i=rows.value.findIndex(r=>r._key===row._key);rows.value.splice(i,1,value);}else rows.value.unshift(value);rows.value=[...rows.value];tick.value++;}else{await api.save(resource,cleanRow(value));s.notify('success');await runLoad();}}});}
async function removeRows(targets){if(!targets.length)return;if(screen.value==='admmenu'&&targets.some(r=>isProtected(r,rows.value))){await s.dialog.alert({title:t('notice'),message:t('protected')});return;}const names=targets.map(r=>r.code||r.username||r.name||localeValue(r,state.locale,'label')).join(', ');const ok=await s.dialog.confirm({title:t('confirm_delete'),message:names,description:t(def.value.batch&&screen.value!=='admmsge'?'cascade':'permanent'),danger:true,submitLabel:t('delete')});if(!ok)return;if(def.value.batch){const group=crypto.randomUUID();for(const row of rows.value){if(targets.some(r=>r._key===row._key||(screen.value==='admmenu'&&row.path?.startsWith(r.path+'/')))&&!row._deleted){row._deleted=true;row._deleteGroup=group;}}rows.value=rows.value.filter(r=>!(r._deleted&&!baseline.value.some(b=>b._key===r._key)));selected.value=[];grid.value?.clear();tick.value++;}else{try{for(const row of targets)await api.remove(def.value.resource,row.id);s.notify('success');await runLoad();}catch(e){error.value=errorText(e);}}}
function restore(row){const group=row._deleteGroup;for(const r of rows.value)if(group?r._deleteGroup===group:r._key===row._key){delete r._deleted;delete r._deleteGroup;}rows.value=[...rows.value];tick.value++;}
