async function save(throwError=false){grid.value?.stop();tick.value++;const batch=changes.value;if(!changeCount.value)return;saving.value=true;error.value='';try{if(def.value.resource==='i18n'){const codes=rows.value.filter(r=>!r._deleted).map(r=>r.code);if(new Set(codes).size!==codes.length)throw Error(t('duplicate'));}for(const row of [...batch.insert,...batch.update]){const v=validate(def.value.resource,row,langs.value);if(v)throw Error(t(v));}await api.persist(def.value.resource,batch);baseline.value=clone(rows.value.filter(r=>!r._deleted));rows.value=clone(baseline.value);tick.value++;s.notify('success');try{await load();}catch{rows.value=[];baseline.value=[];total.value=0;error.value=t('saved_reload');}}catch(e){error.value=errorText(e);if(throwError)throw e;}finally{saving.value=false;}}
async function changeStatus(){await s.dialog.open({kind:'form',title:t('change_status'),message:selected.value.length+' '+t('selected'),initial:{status:statuses[0]},fields:[{path:'status',label:t('select_status'),type:'select',required:true,options:statuses}],onSubmit:async v=>{await api.changeStatus(selected.value.map(r=>r.id),v.status);s.notify('status_done');await runLoad();}});}
async function resetPassword(row){await s.dialog.open({kind:'confirm',title:t('reset_password'),message:t('reset_confirm'),description:row.username+' · '+row.name,onSubmit:async()=>{await api.resetPassword([row.id]);s.notify('reset_done');await runLoad();}});}
async function allPages(resource){let p=1,list=[],result;do{result=await api.list(resource,{page:p,pageSize:200});list.push(...result.contents);p++;}while(p<=result.totalPages);return list;}
async function authorityData(id,detail){const data=detail||await api.detail('authority',id);data.menus=flatten(await api.authorityMenus(id)).filter(m=>m.program?.trim()).map(m=>({id:m.id,authorities:m.authorities||{}}));const users=[];for(const user of data.users||[]){if(typeof user==='object'){users.push(user);continue;}const assigned=await api.userAuthorities(user);const match=assigned.find(a=>a.id===id);if(!match)throw Error(t('missing_dates'));users.push({id:user,applyStartDate:match.applyStartDate||'',applyEndDate:match.applyEndDate||''});}data.users=users;return data;}
async function mapAuthority(row,kind){try{const full=await authorityData(row.id);let items;if(kind==='menus'){items=flatten(await api.authorityMenus(row.id)).map(m=>({id:m.id,name:localeValue(m,state.locale,'label'),subtitle:m.program||m.path,depth:m._depth,assignable:!!m.program?.trim(),authorities:m.program?.trim()?{READ:false,WRITE:false,EXECUTE:false,...clone(m.authorities||{})}:{},selected:!!m.program?.trim()&&Object.values(m.authorities||{}).some(Boolean)}));}else{items=await Promise.all(full.users.map(async u=>{const user=await api.detail('user',u.id);return {...u,name:user.name,subtitle:user.username,selected:true};}));}await s.dialog.open({kind:'mapping',title:t(kind==='menus'?'menu':kind)+' · '+row.name,wide:true,mapping:kind,items,search:kind==='users'?async query=>(await api.authorityUsers(row.id,query)).map(u=>({...u,subtitle:u.username,selected:false,applyStartDate:'',applyEndDate:''})):null,onSubmit:async values=>{const selectedValues=values.filter(v=>v.selected);if(kind==='menus')full.menus=values.filter(v=>v.assignable).map(v=>({id:v.id,authorities:v.authorities}));else full.users=selectedValues.map(v=>({id:v.id,applyStartDate:v.applyStartDate||'',applyEndDate:v.applyEndDate||''}));await api.save('authority',cleanRow(full));s.notify('success');}});}catch(e){error.value=errorText(e);}}
async function mapUser(row){try{const before=await api.userAuthorities(row.id);const available=await allPages('authority');const merged=[...available,...before.filter(a=>!available.some(b=>b.id===a.id))];const items=merged.map(a=>{const old=before.find(b=>b.id===a.id);return {...a,...old,selected:!!old,subtitle:a.role,applyStartDate:old?.applyStartDate||'',applyEndDate:old?.applyEndDate||''};});await s.dialog.open({kind:'mapping',title:t('authorities')+' · '+row.name,wide:true,mapping:'authorities',items,onSubmit:async values=>{const normalized=values.filter(v=>v.selected).map(v=>{const {selected,subtitle,...value}=v;return value;});await api.saveUserAuthorities(row.id,assignmentDiff(before,normalized));s.notify('success');}});}catch(e){error.value=errorText(e);}}
function beforeUnload(e){if(dirty.value||state.dialogs.length){e.preventDefault();e.returnValue='';}}
function keydown(e){if(e.key==='Escape')mobileNav.value=false;if(mobileNav.value&&e.key==='Tab'){const nodes=[...sidebar.value.querySelectorAll('a,button')].filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>{runLoad();window.addEventListener('beforeunload',beforeUnload);window.addEventListener('keydown',keydown);});onBeforeUnmount(()=>{disposed=true;generation++;window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('keydown',keydown);});
</script>
